SourceCode.Declaration:
/// <summary>
/// Data contract class for the MET PurchParm Packing Slip SysOperation task.
/// </summary>
/// <remarks>
/// This contract is used to pass parameters to the SysOperation framework for processing
/// purchase order packing slip-related operations. It includes a flag to determine whether
/// the Continuing Permission Notice (CPN) should be auto-generated. The flag defaults to true.
/// </remarks>
[DataContract]
public class METPurchParmPackingSlipContract extends METSysOperationTaskDataContract
{
    boolean isAutoGenerateCPNotice = true;

}

Method.Source:
/// <summary>
/// Gets or sets the flag indicating whether the Continuing Permission Notice (CPN) should be auto-generated.
/// </summary>
/// <param name="_isAutoGenerateCPNotice">
/// Optional. If provided, sets the internal flag to the given value.
/// </param>
/// <returns>
/// The current value of the isAutoGenerateCPNotice flag.
/// </returns>
/// <remarks>
/// This parameter is exposed in the SysOperation dialog and defaults to true.
/// </remarks>
[DataMember, SysOperationControlVisibilityAttribute(true), SysOperationLabelAttribute("@MET:GenerateAutoCP")]
public Boolean parmIsAutoGenerateCPNotice(Boolean _isAutoGenerateCPNotice = isAutoGenerateCPNotice)
{
    isAutoGenerateCPNotice = _isAutoGenerateCPNotice;

    return isAutoGenerateCPNotice;
}
